/// <summary>
/// Data contract class for  Recalculate attribute cache service
/// </summary>
[DataContractAttribute]
public class METRecalculateAttributeCacheContract //extends SysOperationDataContractBase
{
    private str packedQuery;
    METUpdateParameters updateParameters;
    METDisplayInfoOnUpdate displayInfoOnUpdate;

}

Method.Source:
/// <summary>
/// Gets or sets the packed query string used by the contract.
/// When a value is provided it sets the internal packedQuery field;
/// when called without a parameter it returns the current packed query.
/// </summary>
/// <param name="_packedQuery">Base64-packed query string to store (optional).</param>
/// <returns>The current packed query string.</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(InventTable))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Builds and returns a <c>Query</c> object from the stored packed query.
/// The stored string is base64-decoded and unpacked to construct the Query.
/// </summary>
/// <returns>A <c>Query</c> instance represented by the packed query string.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Packs and stores the supplied <c>Query</c> as a base64-encoded string.
/// This lets the contract persist the Query for later reconstruction via <c>getQuery</c>.
/// </summary>
/// <param name="_query">The <c>Query</c> to pack and store.</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// get/set the Update parameters flag.
/// </summary>
/// <param name="_updateParameters">Optional boolean to store as the update-parameters flag.</param>
/// <returns>Current boolean value of the update-parameters flag.</returns>
[
    DataMemberAttribute('@MET:UpdateParameters'),
    SysOperationDisplayOrderAttribute('1')
]
public METUpdateParameters parmUpdateParameters(METUpdateParameters _updateParameters = updateParameters)
{
    updateParameters = _updateParameters;
    return updateParameters;
}

/// <summary>
/// get/set the Display information on update flag.
/// </summary>
/// <param name="_displayInfoOnUpdate">Optional boolean to store as the display-info-on-update flag.</param>
/// <returns>Current boolean value of the display-info-on-update flag.</returns>
[
    DataMemberAttribute('@MET:DisplayInfoOnUpdate'),
    SysOperationDisplayOrderAttribute('2')
]
public METDisplayInfoOnUpdate parmDisplayInfoOnUpdate(METDisplayInfoOnUpdate _displayInfoOnUpdate = displayInfoOnUpdate)
{
    displayInfoOnUpdate = _displayInfoOnUpdate;
    return displayInfoOnUpdate;
}

/// <summary>
/// Validates that the required MET product parameters are configured.
/// </summary>
/// <returns>
/// Returns true when all required parameters are set; otherwise an error is shown and the method returns false.
/// </returns>
public boolean validate()
{
    EcoResProductParameters ecoResProductParameters = EcoResProductParameters::find();
    boolean ret = true;

    if (!(ecoResProductParameters.METConsumerGSTExempt != 0
            && ecoResProductParameters.METInvoiceCategory != 0
            && ecoResProductParameters.METLevyType != 0
            && ecoResProductParameters.METPricedByWeight != 0
            && ecoResProductParameters.METTempItemForPackChange != 0))
    {
        ret = false;
        ret = error(strFmt('@MET:CacheAtributeSetupValidation', METConstants::ConsumerGSTExempt, METConstants::InvoiceCategory, METConstants::LevyTypeAttributeId, METConstants::PricedByWeightAttributeId, METConstants::TempItemForPackChange));
    }

    return ret;
}
